package com.aistock.notification.alert;
import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.ObjectMapper;import java.net.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AlertMarketUseTransportTest {
 @Test void onlyEvidenceBodyReceivesHeadersMetadataBoundaryAndUserDoNot()throws Exception{var captured=new ArrayList<Map<String,String>>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{var h=new HashMap<String,String>();for(var k:List.of("X-Market-Use-Bundle","X-Market-Use-Owner","X-Market-Use-Purpose","X-Market-Use-Operation","X-Market-Use-Generation")){var v=e.getRequestHeaders().getFirst(k);if(v!=null)h.put(k,v);}captured.add(h);byte[] b="{\"code\":\"OK\",\"data\":{}}".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});server.start();try{var req=new AlertMarketUseClient.Request(UUID.randomUUID().toString(),"1",UUID.randomUUID().toString(),UUID.randomUUID().toString());var receipt=new AlertMarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(req.rawVersionId()));try(var scope=AlertMarketUseContext.open(req,receipt)){var http=new AlertRemoteHttp("http://127.0.0.1:"+server.getAddress().getPort(),"private");http.get("stock-market-service","/internal/v1/market/alert-evidence-references/"+UUID.randomUUID());http.get("stock-market-service","/internal/v1/market/alert-evidence/versions/"+UUID.randomUUID());http.get("stock-market-service","/internal/v1/market/alert-boundary/SH600030");http.get("stock-user-service","/internal/v1/users/"+UUID.randomUUID()+"/alert-context");}assertTrue(captured.get(0).isEmpty());assertEquals(5,captured.get(1).size());assertEquals("notification",captured.get(1).get("X-Market-Use-Owner"));assertTrue(captured.get(2).isEmpty());assertTrue(captured.get(3).isEmpty());assertTrue(AlertMarketUseContext.headers().isEmpty());}finally{server.stop(0);}}
}
